from assemble_topic import assemble, W, read, dump, stamp
FACTS={
'01':('National parks, communal conservancies and specialist conservation centres are different management categories.','A boundary or centre-location map cannot by itself establish wildlife density or management success.'),
'01-01':('The Cheetah Conservation Fund research and education centre is near Otjiwarongo.','The location of a conservation centre is distinct from a map of a species’ full distribution.'),
'01-02':('Etosha National Park is a major northern Namibian conservation area supporting wildlife and nature-based visits.','Its park boundary does not describe every species’ seasonal distribution or population trend.'),
'01-03':('Torra in the north-west and Salambala in the north-east are named communal-conservancy examples.','Communal conservancies have defined member-based governance rather than being identical to national parks.'),
'02':('Wildlife can support tourism, jobs, related services and appropriately managed economic uses.','Revenue, profit, ecological condition and household benefit are different outcomes needing relevant evidence.'),
'03':('Animals influence vegetation, food webs and nutrient movement through species-specific processes.','Concentrated use exceeding vegetation recovery can reduce cover while animal numbers alone do not establish ecological balance.'),
'04':('Environmental change can alter habitat, food, water, movement and conditions for survival or reproduction.','Local counts can change through movement or observation effort as well as population change.'),
'04-01':('Desertification involves degradation in relevant dryland settings rather than the mere existence of desert.','Loss of productive cover or soil function can reduce wildlife resources depending on species needs.'),
'04-02':('Deforestation can remove or fragment habitat and interrupt suitable movement.','A habitat-area percentage loss does not establish an identical percentage loss for every animal population.'),
'04-03':('Global warming can alter heat exposure, water and habitat conditions through relevant regional pathways.','A short hot spell is not equivalent to a measured long-term climate trend or an exact wildlife impact.'),
'05':('Wildlife and agriculture or settlement can conflict through damage, predation, access or habitat change.','The costs and benefits can fall on different households and need appropriate participation and evidence.'),
'06':('Sustainable wildlife management requires relevant ecological recovery and workable human benefit arrangements.','Government, NGOs, private operators, local authorities and communities have different complementary roles.'),
'06-01':('Government rules, coordination and enforcement depend on suitable evidence, capacity and compliance.','A permit does not change a population’s recovery balance or prove a sustainable outcome.'),
'06-02':('NGOs can contribute research, training and technical support when appropriate and usable.','Training attendance and monitoring effort are different from demonstrated ecological or livelihood improvement.'),
'06-03':('Private enterprises can provide capital, operating skills, employment and payments under suitable arrangements.','A signed agreement does not establish fulfilled terms or fair household distribution.'),
'06-04':('Local authorities can influence relevant land-use, infrastructure, waste and service decisions within their responsibilities.','Constructing a service asset is distinct from maintaining it and observing the intended environmental outcome.'),
'06-05':('Community knowledge, rights, participation and experience inform wildlife decisions.','A committee or majority among a limited sample does not establish unanimous consent or equal benefits.')}
CARDS={
'001':('Name the major Namibian national park associated with its pan and wildlife-viewing waterholes.','Etosha National Park.',['1 mark for the park name Etosha.']),
'002':('Describe the supplied Namibia conservation-location map, distinguishing Etosha, the Cheetah Conservation Fund near Otjiwarongo, and Torra/Salambala conservancy examples.','Etosha is a northern park area; the Cheetah Conservation Fund is a specialist centre near Otjiwarongo; Torra and Salambala are separate north-western and north-eastern conservancy examples. The key distinguishes area categories from the centre point.',['1 mark for the park/centre spatial pattern; 1 for named conservancy map evidence; 1 for the key/category distinction.']),
'003':('Name the Namibian town near the Cheetah Conservation Fund’s research and education centre.','Otjiwarongo.',['1 mark for the town name Otjiwarongo.']),
'004':('Name the broad part of Namibia containing Etosha National Park.','Northern Namibia.',['1 mark for the relevant regional-location point.']),
'005':('Name one northern communal-conservancy example and its broad setting.','Torra in the north-west or Salambala in the north-east.',['1 mark for one complete name/location pair.']),
'006':('Explain how wildlife can support local income through suitable nature-based tourism arrangements.','Wildlife attracts relevant visits, creating demand for guiding, accommodation or other services. Payments can support jobs and local suppliers. The local benefit depends on actual access, sourcing and distribution, not animal presence alone.',['1 mark for wildlife attraction as a factor; 1 for the visitor-demand link; 1 for service payments; 1 for the conditional local-income effect.']),
'007':('Describe what this record establishes: wildlife visits and enterprise receipts increase, but household distribution and complete costs are absent.','The observed activity and receipts rise. The record does not establish profit or equal household gains. Those outcomes need cost and distribution evidence beyond the visitor trend.',['1 mark for the rising-activity pattern; 1 for receipt/missing-data evidence; 1 for the bounded economic interpretation.']),
'008':('Explain how animal use concentrated around a water point can affect vegetation where removal exceeds regrowth.','Concentration increases local feeding or trampling pressure. With inadequate recovery, cover declines and soil can become more exposed. Under suitable conditions this can increase erosion and weaken later forage recovery.',['1 mark for concentration as a factor; 1 for the use/recovery link; 1 for reduced cover; 1 for its conditional soil/forage effect.']),
'009':('Describe the environmental record: animal use increases near one water point and plant cover declines there; the rest of the landscape is not measured.','The record shows a local association of use and cover change. It does not establish the same condition throughout the region or isolate use from all other causes. Wider matched habitat and recovery observations are needed.',['1 mark for the local relationship; 1 for site/coverage evidence; 1 for the bounded extent/attribution interpretation.']),
'010':('Explain a pathway from woodland clearance to reduced opportunity for a tree-dependent animal population.','Clearance removes a needed habitat resource. Remaining patches can become smaller or harder to move between, reducing access to food, shelter or breeding opportunities. Effects depend on the species and alternatives rather than an identical response by all wildlife.',['1 mark for clearance as a factor; 1 for the habitat/fragmentation link; 1 for a specific lost resource; 1 for the conditional population-opportunity effect.']),
'011':('Describe the supplied schematic habitat-change diagram: connected tree cover becomes two separated patches after a clearing corridor; no animal counts are supplied.','Tree habitat becomes reduced or fragmented and the earlier connection is interrupted. The figure supports a possible movement/resource constraint for relevant species. It does not establish an exact animal-population loss without count and species-use evidence.',['1 mark for the fragmentation pattern; 1 for the changed-connection evidence; 1 for the bounded ecological interpretation.']),
'012':('Name the dryland process involving persistent degradation of productive land rather than simply a desert existing.','Desertification.',['1 mark for the process name desertification.']),
'013':('Name the environmental change removing forest or woodland cover and potentially fragmenting habitat.','Deforestation.',['1 mark for the process name deforestation.']),
'014':('Name the long-term increase in global average temperature, distinct from one hot day.','Global warming.',['1 mark for the process name global warming.']),
'015':('Explain why a wildlife-management scheme can face conflict even while total tourism receipts rise.','Some households can bear crop or livestock losses while other people receive tourism income. Aggregate receipts do not establish compensation or benefit access for those affected. Unequal costs and benefits can therefore create disagreement about land use or management.',['1 mark for uneven damage as a factor; 1 for the beneficiary/cost link; 1 for absent demonstrated distribution; 1 for the conflict effect.']),
'016':('Describe the stakeholder record: A receives tourism wages while B loses livestock and has no recorded support payment.','The experiences differ: A has an income benefit and B a stated loss. The record does not support equal household benefit or compensation. A wider distribution judgement needs additional household and agreement evidence.',['1 mark for the unequal-outcome pattern; 1 for paired household evidence; 1 for the bounded distribution interpretation.']),
'017':('Name the stakeholder category supplying specialist conservation research or training outside government and commercial operation.','A non-governmental organisation or NGO.',['1 mark for the stakeholder name NGO.']),
'018':('How far do you agree that more animals counted alone proves sustainable wildlife management? Survey effort and habitat recovery are unrecorded, and no livelihood evidence is supplied.','Disagree. Counts can change with effort or movement as well as population size. Habitat recovery and human costs or benefits are also relevant to the stated management aim. More counted animals is an observation, not a complete sustainability verdict.',['Up to 4 C marks for judgement using count/effort evidence and missing habitat or livelihood conditions.','1 C mark for a supported decision against demonstrated sustainability.']),
'019':('How far do you agree that permit compliance proves maintained population here? Opening stock is 100, additions twenty and removals/losses thirty; other changes are absent, and all permitted limits are followed.','Disagree: closing stock is ninety, a ten-animal decline. Compliance does not change that balance. The rule’s ecological basis and wider recovery evidence need reassessment before maintained stock is claimed.',['Up to 4 C marks for judgement using the stock evidence, decline and rule/outcome distinction.','1 C mark for a supported maintained-stock decision.']),
'020':('How far do you agree that an NGO training twenty people proves its wildlife outcomes improved? Attendance is recorded, but later practice, habitat or population results are absent.','Disagree that the outcome is established. Attendance shows an input to capacity, not application or ecological improvement. Relevant practice and resource monitoring are needed, while the training may still have useful potential.',['Up to 4 C marks for judgement using attendance evidence and the missing practice/resource links.','1 C mark for a supported decision distinguishing participation from outcome.']),
'021':('How far do you agree that a signed private tourism agreement proves fair payments reached community households? No fulfilment or distribution records are supplied.','Disagree. The agreement provides terms, while delivered payments and their distribution remain unverified. Accessible records and affected members’ evidence are needed. Potential capital or employment benefits do not establish fair household receipt on their own.',['Up to 4 C marks for judgement using the agreement evidence and missing fulfilment/distribution conditions.','1 C mark for a supported fairness/delivery decision.']),
'022':('How far do you agree that constructing a local waste facility proves wildlife-related pollution declined? Collection and operation are unrecorded and no before/after quality observations exist.','Disagree. An asset exists, but use, maintenance and environmental outcomes are unmeasured. A functioning collection/treatment chain and relevant condition records are needed. Construction may enable improvement without establishing it.',['Up to 4 C marks for judgement using construction evidence, operating requirements and missing outcome observations.','1 C mark for a supported environmental-success decision.']),
'023':('How far do you agree that a committee’s approval proves every conservancy member benefits and agrees? Remote households were not consulted and distribution records are absent.','Disagree. A representative decision is not evidence of unanimous views or equal gains. The missing households and distribution records limit the claim. Wider accessible participation and benefit evidence are needed without assuming that disagreement removes every possible programme benefit.',['Up to 4 C marks for judgement using participation evidence, distribution gaps and representative/unanimous distinctions.','1 C mark for a supported decision about the claimed universal benefit/consent.'])}
TASKS=[
{'objectives':['01','02','05'],'prompt':'(a) Name the town near the Cheetah Conservation Fund centre. [1]\n(b) Describe three distinct ways wildlife can contribute to people’s activities or livelihoods under suitable management. [3]\n(c) Name the major park associated with the Etosha pan. [1]\n(d) Describe the contrast: one household receives tourism wages while another records livestock losses and no support payment. [2]','answer':'(a) Otjiwarongo. (b) Wildlife viewing can support guiding or accommodation; suitable suppliers can gain demand; relevant research or appropriately managed products can provide benefits. Credit three distinct linked contributions. (c) Etosha National Park. (d) Benefits and costs fall differently; aggregate tourism gains do not establish compensation for the household with losses.','guide':['(a) 1 A mark for Otjiwarongo.','(b) 3 A marks for three distinct contribution point descriptions.','(c) 1 A mark for Etosha National Park.','(d) 2 B marks for the paired difference and the distribution interpretation.'],'split':{'A':5,'B':2},'parts':[('a','Name',1,'A'),('b','Describe',3,'A'),('c','Name',1,'A'),('d','Describe',2,'B')]},
{'objectives':['03','04','06'],'prompt':'A hypothetical managed wildlife stock begins with 100 animals. Births and immigration add twenty; stated removals and deaths total thirty. Other changes are absent. A separate local survey observes ten animals in one hour before and twenty in four hours after; methods and detection are otherwise unspecified.\n(a) Name the ecological resource needed to support continued wildlife use, such as suitable vegetation, water and shelter together. [1]\n(b) Calculate closing stock in the simplified account. [2]\n(c) Describe three distinct stock or observation-effort features supported by the data. [3]\n(d) What judgement is supported about the claim “the later local survey proves population doubling”? [1]','answer':'(a) Habitat or suitable habitat resources. (b) 100+20−30 = 90 animals. (c) Losses exceed additions by ten; managed stock falls 10% from opening; the separate observed count doubles while effort rises fourfold. Credit three distinct features, treating equivalent stock-decline expressions as one. Raw totals are not directly comparable population estimates. (d) Doubling is not established because effort and detection information limit the inference.','guide':['(a) 1 A mark for suitable habitat.','(b) 2 B marks for complete stock-balance method and ninety animals.','(c) 3 B marks for one stock-balance pattern, the separate raw-count change and observation-effort change, using resource values.','(d) 1 C mark for a supported judgement about unmatched survey evidence.'],'split':{'A':1,'B':5,'C':1},'parts':[('a','Name',1,'A'),('b','Calculate',2,'B'),('c','Describe',3,'B'),('d','What',1,'C')]},
{'objectives':['01','05','06'],'prompt':'How far do you agree that a communal conservancy’s committee and wildlife plan alone establish successful sustainable use? Namibia’s Ministry describes communal conservancies as member-based arrangements with elected committees and reporting responsibilities. This question supplies no subsequent habitat, population, conflict-loss or benefit-distribution records. Judge what is and is not demonstrated. [5]','answer':'Disagree that overall success is established. Governance arrangements and a plan provide a framework, but their operation and outcomes need evidence. Suitable wildlife/habitat trends, compliance, conflict costs and delivered benefits are relevant to sustainable use. Members may experience different results. The institutional arrangement has potential without proving maintained resources or fair livelihood outcomes on its own.','guide':['Up to 4 C marks for judgement using the institutional evidence, missing ecological and distribution results and relevant conflict/participation limits.','1 C mark for a supported decision distinguishing framework from demonstrated sustainability.'],'split':{'C':5},'parts':[('a','How far do you agree',5,'C')]}
]
SOURCES=[('MEFT-ETOSHA','https://meft.gov.na/national-parks/etosha-national-park/217/'),('MEFT-CONSERVANCIES','https://www.meft.gov.na/services/conservancies/193/'),('NACSO-CONCESSIONS','https://nacso.org.na/tourism-concessions/'),('CCF-FACTS-2023','https://cheetah.org/wp-content/uploads/2021/11/CCFFactSheets2023.pdf'),('UNCCD-DEFINITION','https://www.unccd.int/article-1-use-terms'),('IPCC-NATURE-IMPACTS','https://www.ipcc.ch/report/ar6/wg2/about/frequently-asked-questions/keyfaq2/')]
if __name__=='__main__':
 assemble('2.6',FACTS,CARDS,TASKS,SOURCES)
 td=W/'topics/2.6';wo=read(td/'work_order.json');p=td/wo['output_files']['learning_items'];d=read(p)
 for item in d['items']:
  if item['item_id']=='ITEM-6137-2.6-002-INTERP':
   item['context']['situation']='VISUAL PENDING: Namibia conservation-location map required; approved visual plan has only the habitat-change figure for this topic. Proposed planner-approved original overlay or explicit base-map reuse, not yet authorised as a new planned resource.'
   stamp(item,item['claim_ids'])
 dump(p,d)
 n=read(td/'authoring_notes.json');n['scope_concerns']=[{'affected_items':['ITEM-6137-2.6-002-INTERP'],'issue':'Map interpretation has no assigned map in the approved visual plan.','proposed_repair':'Planner to approve a sourced Namibia conservation overlay or explicit appropriate map reuse; author has not changed approved counts or planner files.','status':'open'}];n['terminology_note']='The syllabus cheetah-foundation reference is taught using the correctly named Cheetah Conservation Fund near Otjiwarongo; the objective identifier and labels are unchanged.';dump(td/'authoring_notes.json',n)
